async function generateImage(){snapshot();const button=$('#generate-image'),cancel=$('#cancel-image');button.disabled=true;button.textContent='正在生成…';cancel.classList.remove('hidden');const index=current,w=work(),p=w.panels[index],prompt=makePrompt(w,p);p.generationStatus='running';const create=await fetch('/api/v1/jobs',{method:'POST',headers:{'content-type':'application/json','idempotency-key':'panel-'+p.id+'-'+Date.now()},body:JSON.stringify({type:'panel_image',input:{workId:w.id,panelId:p.id,prompt}})});if(!create.ok){button.disabled=false;button.textContent='✦ 生成这一格';cancel.classList.add('hidden');toast((await create.json()).error?.message||'无法创建任务');return}let job=await create.json();activeJobId=job.id;for(let i=0;i<720&&!['succeeded','failed','cancelled'].includes(job.status);i++){await new Promise(resolve=>setTimeout(resolve,1000));const poll=await fetch('/api/v1/jobs/'+job.id);if(poll.ok)job=await poll.json()}activeJobId=null;button.disabled=false;button.textContent='✦ 生成这一格';cancel.classList.add('hidden');if(job.status!=='succeeded'){p.generationStatus=job.status==='cancelled'?'cancelled':'failed';persist();renderPanelListOnly();toast(job.error?.message||'生成失败，可重试');return}const latest=await fetch('/api/v1/state').then(r=>r.json());if(latest?.state){db=latest.state;serverRevision=latest.revision||serverRevision}p=work().panels[index];p.generationStatus='succeeded';renderWorkbench();toast(job.result?.mode==='ai'?'AI 画面已生成，新版本已保存':'演示版本已记录；配置绘图模型后可生成真实画面')}
async function generateStory(){snapshot();const w=work(),character=db.characters.find(c=>c.id===w.characterId),count=Math.max(1,Math.min(20,w.panels.length));const job=await runJob('storyboard',{workId:w.id,panelCount:count,premise:w.premise,title:w.title,tone:w.tone||'轻松、温暖，带有职场反转',audience:w.audience||'微信公众号漫画读者',ending:w.ending||'有笑点并形成完整收束',characters:character?[{name:character.name,summary:character.summary,look:character.look,style:character.style}]:[]});if(job.status!=='succeeded'){toast(job.error?.message||'分镜生成失败，请重试');return}const result=job.result||{},generated=result.mode==='ai'&&Array.isArray(result.panels)?result.panels:Array.from({length:count},(_,i)=>samplePanels[i%samplePanels.length]);w.panels=generated.map((panel,i)=>{const old=w.panels[i]||{};return {...old,...panel,id:old.id||'p'+Date.now()+'-'+i,versions:old.versions||[1],version:old.version||1,imageVersions:old.imageVersions||[]}});if(result.title&&result.mode==='ai')w.title=result.title;current=0;w.updatedAt=Date.now();persist();renderWorkbench();toast(result.mode==='ai'?'AI 分镜已生成，可逐格修改':'演示分镜已载入，可逐格修改')}
